-- Phase 2 · TaxPay source candidate provenance, NOT approved payment heads.
-- Preserve original v11 transcription byte-identically in reference/v11_original_170_heads_UNVERIFIED.json.
-- This migration is additive, insert-only, and enables no executable payment heads.
BEGIN;
CREATE TABLE public.taxpay_source_snapshots (
  source_key text PRIMARY KEY,
  source_kind text NOT NULL DEFAULT 'PROTOTYPE_TRANSCRIPTION'
    CHECK (source_kind = 'PROTOTYPE_TRANSCRIPTION'),
  prototype_document_sha256 text NOT NULL CHECK (prototype_document_sha256 ~ '^[a-f0-9]{64}$'),
  original_workbook_reference text NOT NULL,
  source_locator text NOT NULL,
  record_count integer NOT NULL CHECK (record_count = 170),
  legal_verification_status text NOT NULL DEFAULT 'UNVERIFIED'
    CHECK (legal_verification_status = 'UNVERIFIED'),
  imported_at timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE public.taxpay_source_snapshots IS
  'Immutable-by-policy v11 reference metadata; NOT an NBR/ACS gazette or approved accounting master';
CREATE TABLE public.taxpay_head_source_candidates (
  source_key text NOT NULL REFERENCES public.taxpay_source_snapshots(source_key) ON DELETE RESTRICT,
  source_head_id integer NOT NULL CHECK (source_head_id BETWEEN 1 AND 170),
  legacy_source_code_en text NOT NULL,
  legacy_source_code_bn text NOT NULL,
  source_label_en text NOT NULL,
  source_label_bn text,
  source_group_en text NOT NULL,
  source_group_bn text NOT NULL,
  source_journey text NOT NULL CHECK (source_journey IN ('LIABILITY', 'WITHHOLDING')),
  source_map text NOT NULL CHECK (source_map IN ('MAPPED','OWNER_REVIEW')),
  raw_original_record jsonb NOT NULL CHECK (jsonb_typeof(raw_original_record) = 'object'),
  verification_status text NOT NULL DEFAULT 'UNVERIFIED'
    CHECK (verification_status = 'UNVERIFIED'),
  executable boolean NOT NULL DEFAULT false CHECK (executable = false),
  verified_act_2023_section text CHECK (verified_act_2023_section IS NULL),
  verified_acs_economic_code text CHECK (verified_acs_economic_code IS NULL),
  PRIMARY KEY (source_key, source_head_id)
);
COMMENT ON TABLE public.taxpay_head_source_candidates IS
  'Reference-only, unapproved v11 head snapshot. Never use these for financial execution';
CREATE INDEX taxpay_head_candidates_source_group_idx ON public.taxpay_head_source_candidates(source_key,source_group_en);
ALTER TABLE public.taxpay_source_snapshots ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.taxpay_source_snapshots FORCE ROW LEVEL SECURITY;
ALTER TABLE public.taxpay_head_source_candidates ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.taxpay_head_source_candidates FORCE ROW LEVEL SECURITY;
REVOKE ALL ON public.taxpay_source_snapshots FROM PUBLIC, anon, authenticated;
REVOKE ALL ON public.taxpay_head_source_candidates FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.taxpay_source_snapshots TO anon, authenticated;
GRANT SELECT ON public.taxpay_head_source_candidates TO anon, authenticated;
CREATE POLICY taxpay_source_snapshot_public_read_only ON public.taxpay_source_snapshots
  FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY taxpay_source_head_public_read_only ON public.taxpay_head_source_candidates
  FOR SELECT TO anon, authenticated USING (true);
INSERT INTO public.taxpay_source_snapshots
